import { api } from './authService';

const reservationService = {
  /** GET /reservations — ADMIN / RECEPTIONNISTE */
  getAll: async (params = {}) => {
    const { data } = await api.get('/reservations', { params });
    return data?.data ?? data;
  },

  /** GET /reservations/my — CLIENT */
  getMyReservations: async () => {
    const { data } = await api.get('/reservations/my');
    return data?.data ?? data;
  },

  /** GET /reservations/{id} */
  getById: async (id) => {
    const { data } = await api.get(`/reservations/${id}`);
    return data?.data ?? data;
  },

  /** POST /reservations */
  create: async (payload) => {
    const { data } = await api.post('/reservations', payload);
    return data?.data ?? data;
  },

  /** PUT /reservations/{id} */
  update: async (id, payload) => {
    const { data } = await api.put(`/reservations/${id}`, payload);
    return data?.data ?? data;
  },

  /** PATCH /reservations/{id}/cancel */
  cancel: async (id) => {
    const { data } = await api.patch(`/reservations/${id}/cancel`);
    return data?.data ?? data;
  },

  /** PATCH /reservations/{id}/check-in */
  checkIn: async (id) => {
    const { data } = await api.patch(`/reservations/${id}/check-in`);
    return data?.data ?? data;
  },

  /** PATCH /reservations/{id}/check-out */
  checkOut: async (id) => {
    const { data } = await api.patch(`/reservations/${id}/check-out`);
    return data?.data ?? data;
  },

  /** DELETE /reservations/{id} — ADMIN only */
  delete: async (id) => {
    const { data } = await api.delete(`/reservations/${id}`);
    return data?.data ?? data;
  },
};

export default reservationService;
